'use strict';
const $=id=>document.getElementById(id), C=UAV, KEY='uav-collab-v1', VERSION='1.0.0';
let records=[],session,scenario=C.scenarios[0],state,trial=0,expanded=false,drag=null,dirty=false,lastTick=performance.now(),toastTimer,readOnly=false;
const fresh=()=>({node:scenario.id,route:C.clone(scenario.initialRoute||C.base),proposal:C.clone(scenario.route),altitude:60,speed:8,battery:scenario.battery,progress:0,simTime:0,status:'ready',decision:null,presentedAt:null,editing:false,triggered:false,pausedForVisibility:false,draft:{altitude:60,speed:8,rationale:'',strategy:'recommended'}});
const labels={map_pan:'地图平移',map_zoom:'地图缩放',map_layer:'底图切换',map_recenter:'定位任务区域',session_start:'新会话',node_select:'切换节点',scenario_trigger:'情境触发',accept:'接受方案',reject:'拒绝方案',modify_open:'打开修改',modify_cancel:'取消修改',modify_apply:'应用修改',waypoint_move:'移动航点',waypoint_select:'查看航点',strategy_change:'切换方案',parameter_change:'修改参数',simulation_start:'开始模拟',simulation_pause:'暂停模拟',simulation_resume:'继续模拟',simulation_complete:'任务完成',node_reset:'重置节点',sat_change:'呈现切换',participant_change:'参与者设置',validation_failed:'约束未通过',details_open:'展开信息',details_close:'收起信息',export:'导出记录',reload:'恢复会话',visibility_pause:'离开页面暂停',visibility_resume:'返回页面',session_end:'结束会话'};
function snapshot(){return {node:scenario.id,route:C.clone(state.route),proposal:C.clone(state.proposal),altitude:state.altitude,speed:state.speed,battery:state.battery,progress:state.progress,simTime:state.simTime,status:state.status,decision:state.decision,editing:state.editing,triggered:state.triggered,draft:C.clone(state.draft),mapReference:window.MAP_REFERENCE||null}}
function persist(){if(readOnly)return;try{localStorage.setItem(KEY,JSON.stringify({version:VERSION,records,session,trial,node:scenario.id,state}));dirty=false;$('storageStatus').textContent='已保存 · 当前浏览器'}catch(e){$('storageStatus').textContent='本地保存失败，请立即导出记录';}}
function log(type,detail='',before=null,extra={}){const at=new Date().toISOString();records.push({id:crypto.randomUUID(),version:VERSION,timestamp:at,sessionId:session.id,participant:session.participant,condition:session.condition,trialId:session.id+'-'+trial,node:scenario.id,type,label:labels[type]||type,detail,reactionMs:null,before,after:snapshot(),...extra});dirty=true;persist();renderLogs()}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3500)}
function newSession(initial=false){if(!initial){log('session_end','开始新会话，旧记录保留');}session={id:crypto.randomUUID(),participant:$('participant').value.trim()||'P001',condition:$('satMode').value,createdAt:new Date().toISOString()};trial=1;state=fresh();log('session_start','探索模式；AI 与环境均为规则模拟');render()}
function load(){let raw;try{raw=localStorage.getItem(KEY)}catch(e){$('storageStatus').textContent='浏览器不允许本地存储；请导出记录'}if(raw){try{const saved=JSON.parse(raw);if(saved.version!==VERSION||!Array.isArray(saved.records)||!saved.session||!saved.state||!C.scenarios.some(x=>x.id===saved.node))throw Error('数据结构不匹配');records=saved.records;session=saved.session;trial=saved.trial;scenario=C.scenarios.find(x=>x.id===saved.node);state=saved.state;state.draft??={altitude:state.altitude,speed:state.speed,rationale:'',strategy:'recommended'};const before=snapshot();if(state.status==='running')state.status='paused';$('participant').value=session.participant;$('satMode').value=session.condition;log('reload','已恢复保存状态；运行中的仿真保持暂停，决策时间包含离开页面的时间',before);render();return}catch(e){readOnly=true;$('storageStatus').textContent='旧数据无法读取，已保留原始存储；本轮请使用导出';}}newSession(true)}
function selectNode(id){const before=snapshot();scenario=C.scenarios.find(x=>x.id===id);trial++;state=fresh();log('node_select',scenario.name,before);render()}
function routeString(route){return route.map(p=>p.join(',')).join(' ')}
function svgEl(tag,attrs){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [key,value]of Object.entries(attrs))el.setAttribute(key,value);return el}
function renderMap(){const proposalVisible=state.triggered&&(!state.decision||state.editing);$('originalRoute').setAttribute('points',routeString(scenario.initialRoute||C.base));$('activeRoute').setAttribute('points',routeString(state.route));$('suggestedRoute').setAttribute('points',proposalVisible?routeString(state.proposal):'');$('waypoints').replaceChildren();const points=state.editing?state.proposal:state.route;points.slice(0,-1).forEach((p,i)=>{const g=svgEl('g',{transform:`translate(${p[0]} ${p[1]})`,class:'waypoint'+(state.editing?' editing':''),tabindex:0,role:'button','aria-label':i===0?(scenario.initialRoute?'当前起始位置':'起降点'):`航点 ${i}，位置 ${p[0]}, ${p[1]}`,'data-index':i});g.append(svgEl('circle',{r:i===0?14:11,fill:'#172d2c',stroke:state.editing?'#eab56b':'#7ce2bf','stroke-width':2}));const t=svgEl('text',{'text-anchor':'middle',y:4,fill:'#d2f0e4','font-size':11});t.textContent=i===0?(scenario.initialRoute?'S':'H'):i;g.append(t);$('waypoints').append(g)});if(scenario.initialRoute){const home=svgEl('g',{transform:'translate(130 525)'});home.append(svgEl('circle',{r:13,fill:'#172d2c',stroke:'#7ce2bf','stroke-width':2}));const label=svgEl('text',{'text-anchor':'middle',y:4,fill:'#d2f0e4','font-size':11});label.textContent='H';home.append(label);$('waypoints').append(home)}$('hazards').replaceChildren();if(state.triggered&&scenario.hazard){const h=scenario.hazard;$('hazards').append(svgEl('circle',{cx:h.x,cy:h.y,r:h.r+h.margin,fill:'#eab56b11',stroke:'#eab56b','stroke-dasharray':'6 6'}));$('hazards').append(svgEl('circle',{cx:h.x,cy:h.y,r:h.r,fill:'#e5846b22',stroke:'#dc9074'}));const txt=svgEl('text',{x:h.x,y:h.y+5,'text-anchor':'middle',fill:'#f0bf9a','font-size':12});txt.textContent=scenario.id==='N4'?'预测冲突区':'模拟限制区';$('hazards').append(txt);if(scenario.id==='N4'){$('hazards').append(svgEl('path',{id:'traffic',d:'M-8 0H8M0-8V8',stroke:'#ffbc91','stroke-width':3,transform:`translate(${h.x} ${h.y})`}))}}updateTelemetry()}
function renderSat(){const changed=JSON.stringify(state.proposal)!==JSON.stringify(scenario.route);const estimate=C.estimate(state.proposal,scenario.battery,state.editing?Math.max(2,Number(state.draft.speed)||8):state.speed);const cards=[{id:'action',title:'目标、行动与进展',level:'SAT 1',text:`目标：${scenario.goal}。${state.triggered?(changed?'当前方案已被修改，请以地图路线和更新的预计结果为准。':scenario.summary):'开始模拟后呈现该节点建议。'}`,detail:`当前：${statusText()}；任务进度 ${Math.round(state.progress*100)}%。当前执行表现：仅有模拟位置、速度与进度，未评估任务质量。`},{id:'reason',title:'决策理由与约束',level:'SAT 2',text:(changed?'原始推荐依据（修改后需重新检查）：':'')+scenario.reason,detail:'坐标以演示地图为参考，1 单位按 1 模拟米计算。高度允许范围 30–150 m，速度 2–12 m/s，返航余量下限 15%。'},{id:'projection',title:'预计结果与不确定性',level:'SAT 3',text:`按当前候选方案：航程约 ${estimate.distance} 模拟米，预计 ${formatTime(estimate.seconds)}，返航电量约 ${estimate.endBattery}%。${scenario.id==='N5'?'将放弃部分巡检目标。':''}`,detail:`局限：${scenario.limits} 出错可能性：${scenario.error} 既往表现：${scenario.history} 估算按恒速、每模拟米消耗 0.016% 电量计算。`}];$('satCards').replaceChildren();cards.forEach(card=>{const div=document.createElement('article');div.className='sat-card'+(card.id===session.condition?' emphasis':'');const title=document.createElement('div');title.className='sat-title';title.textContent=card.title;const level=document.createElement('span');level.textContent=card.level+(card.id===session.condition?' · 侧重':'');title.append(level);const p=document.createElement('p');p.textContent=state.triggered?card.text:'等待情境触发后显示完整信息';div.append(title,p);if(state.triggered){const details=document.createElement('details');details.dataset.card=card.id;const summary=document.createElement('summary');summary.textContent='查看完整说明';const extra=document.createElement('p');extra.textContent=card.detail;if(card.id==='action')extra.id='liveActionDetails';details.append(summary,extra);details.addEventListener('toggle',()=>{if(details.isConnected)log(details.open?'details_open':'details_close',`${card.level} 完整说明`)});div.append(details)}$('satCards').append(div)})}
function statusText(){return {ready:'待命',review:'等待决策',approved:'已确认 · 待继续',rejected:'已拒绝 · 保持',running:'执行中',paused:'已暂停',complete:'任务完成'}[state.status]||state.status}
function render(){if(window.missionMap)window.missionMap.invalidateSize();document.querySelectorAll('.node').forEach(b=>{b.classList.toggle('active',b.dataset.node===scenario.id);b.setAttribute('aria-pressed',b.dataset.node===scenario.id)});$('missionTitle').textContent=scenario.name;$('eventBanner').textContent=state.triggered?scenario.event:'按「开始模拟」触发本节点，仿真将等待你的决策。';$('eventBanner').classList.toggle('warning',state.triggered&&scenario.id!=='N1');$('recLabel').textContent=state.status==='complete'?'本轮已完成':state.decision&&state.decision!=='reject'?'已确认方案':state.triggered?'建议已生成 · 等待协作':'准备就绪';$('recTitle').textContent=state.triggered?scenario.title:'复核任务，开始本轮模拟';$('recSummary').textContent=state.triggered?(state.decision==='reject'?'方案已拒绝，系统保持暂停。可修改建议或重新接受。':state.decision?(state.status==='complete'?'本轮任务已完成，已返回起降区。':state.status==='running'?'正在沿已确认的方案执行任务。':'已应用选择的方案，点击「继续模拟」执行。'):scenario.summary):'开始后同时提供行动、理由和预测信息，操作者保留决策权。';const actionable=state.triggered&&['review','rejected'].includes(state.status)&&!state.editing;['accept','modify','reject'].forEach(id=>$(id).disabled=!actionable);$('reject').disabled=!actionable||state.status==='rejected';$('editor').hidden=!state.editing;if(state.editing){$('editAlt').value=state.draft.altitude;$('editSpeed').value=state.draft.speed;$('strategy').value=state.draft.strategy;$('rationale').value=state.draft.rationale;}$('decisionPanel').hidden=state.editing;$('play').disabled=state.editing||['running','review','rejected','complete'].includes(state.status);$('play').textContent=state.status==='ready'?'▶ 开始模拟':'▶ 继续模拟';$('pause').disabled=state.status!=='running';$('participant').disabled=state.triggered;$('satMode').disabled=state.triggered;$('sessionId').textContent='SESSION '+session.id.slice(0,8);renderSat();renderMap();renderLogs()}
function formatTime(seconds){seconds=Math.floor(seconds);return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function updateTelemetry(){if($('liveActionDetails'))$('liveActionDetails').textContent='当前：'+statusText()+'；任务进度 '+Math.round(state.progress*100)+'%。当前执行表现：仅有模拟位置、速度与进度，未评估任务质量。';const pos=C.sample(state.route,state.progress);$('drone').setAttribute('transform',`translate(${pos.x} ${pos.y}) rotate(${pos.heading})`);$('flightStatus').textContent=(state.status==='running'?'FLYING':state.status==='complete'?'DONE':'HOLD')+' · '+statusText();$('flightStatus').classList.toggle('running',state.status==='running');$('altitude').textContent=state.status==='complete'?0:state.altitude;$('speed').textContent=state.status==='running'?state.speed.toFixed(1):'0.0';$('battery').textContent=state.battery.toFixed(1);$('progress').textContent=Math.round(state.progress*100);$('elapsed').textContent=formatTime(state.simTime);$('waypointInfo').textContent=state.status==='complete'?'已返回起降区':`下一目标 WP ${String(pos.next).padStart(2,'0')}`;if(state.presentedAt&&!state.decision)$('reactionClock').textContent=((Date.now()-state.presentedAt)/1000).toFixed(1)+' s';else $('reactionClock').textContent=state.decision?'决策已记录':'尚未触发';if($('traffic')){$('traffic').setAttribute('transform',`translate(${350+Math.sin(state.simTime/8)*50} ${245+Math.sin(state.simTime/8)*15})`)}}
function trigger(){const before=snapshot();state.triggered=true;state.status='review';state.presentedAt=Date.now();log('scenario_trigger',scenario.event,before,{stimulus:{scenario:C.clone(scenario),condition:session.condition,estimate:C.estimate(state.proposal,scenario.battery,state.speed),shownAt:state.presentedAt}});render()}
function decision(kind){const before=snapshot();if(kind==='accept'){const errors=C.validate(state.proposal,scenario,state.altitude,state.speed);if(errors.length){log('validation_failed',errors.join('；'),before);toast(errors.join('；'));return}state.route=C.clone(state.proposal);state.status='approved'}else state.status='rejected';state.decision=kind;log(kind,kind==='accept'?'接受当前候选路线；等待继续模拟':'拒绝建议，保留原路线并保持暂停',before,{reactionMs:Date.now()-state.presentedAt});render()}
function openEditor(){const before=snapshot();state.editing=true;state.draft={altitude:state.altitude,speed:state.speed,rationale:'',strategy:'recommended'};$('editAlt').value=state.altitude;$('editSpeed').value=state.speed;$('strategy').value='recommended';state.proposal=C.clone(scenario.route);$('rationale').value='';$('validation').textContent='';log('modify_open','编辑候选路线和参数',before);render()}
function applyEditor(){const before=snapshot();const altitude=Number($('editAlt').value),speed=Number($('editSpeed').value);state.draft={altitude,speed,rationale:$('rationale').value,strategy:$('strategy').value};const errors=C.validate(state.proposal,scenario,altitude,speed);if(errors.length){$('validation').textContent=errors.join('；');log('validation_failed',errors.join('；'),before);return}state.route=C.clone(state.proposal);state.altitude=altitude;state.speed=speed;state.editing=false;state.status='approved';state.decision='modify';log('modify_apply','修改后接受方案'+($('rationale').value?'；理由：'+$('rationale').value:''),before,{reactionMs:Date.now()-state.presentedAt,rationale:$('rationale').value});render()}
function renderLogs(){const filtered=records.filter(r=>r.sessionId===session.id);$('logCount').textContent=filtered.length;$('logBody').replaceChildren();const visible=expanded?filtered.slice().reverse():filtered.slice(-5).reverse();if(!visible.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='暂无记录';tr.append(td);$('logBody').append(tr)}visible.forEach(r=>{const tr=document.createElement('tr');[new Date(r.timestamp).toLocaleTimeString('zh-CN',{hour12:false}),r.node,r.label,r.detail,r.reactionMs===null?'—':(r.reactionMs/1000).toFixed(2)+' s'].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});$('logBody').append(tr)})}
function csvCell(v){let text=typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}
function exportRecords(format){log('export',`导出全部 ${records.length+1} 条记录为 ${format.toUpperCase()}`);const columns=['id','version','timestamp','sessionId','participant','condition','trialId','node','type','label','detail','reactionMs','before','after','stimulus','rationale'];const data=format==='json'?JSON.stringify({schemaVersion:VERSION,exportedAt:new Date().toISOString(),mode:'preset-simulation',timing:'reactionMs 为情境首次展示至决策的墙钟时间，包含离开页面；时间单位毫秒',records},null,2):'\uFEFF'+columns.join(',')+'\r\n'+records.map(r=>columns.map(k=>csvCell(r[k])).join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:format==='json'?'application/json':'text/csv;charset=utf-8'}));a.href=url;a.download=`uav-collab-${new Date().toISOString().slice(0,10)}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('已导出操作记录')}
for(const node of C.scenarios){const b=document.createElement('button');b.className='node';b.dataset.node=node.id;b.innerHTML=`<span class="number">${node.id}</span><span><strong>${node.name}</strong><small>${node.subtitle}</small></span>`;b.addEventListener('click',()=>{if(state.triggered&&state.status!=='complete'&&!confirm('切换会结束当前节点；已有操作记录会保留。继续？'))return;selectNode(node.id)});$('nodeList').append(b)}
$('play').addEventListener('click',()=>{if(state.status==='ready'){applyResearchConfig();session.participant=$('participant').value.trim()||'P001';log('simulation_start','开始本节点，触发预设情境');trigger();return}const before=snapshot();state.status='running';lastTick=performance.now();log('simulation_resume','以 4 倍仿真时钟执行已确认路线',before);render()});$('pause').addEventListener('click',()=>{const before=snapshot();state.status='paused';log('simulation_pause','用户暂停模拟',before);render()});$('reset').addEventListener('click',()=>{if(state.triggered&&!confirm('重置本节点会开始新一轮，已有记录保留。继续？'))return;const before=snapshot();trial++;state=fresh();log('node_reset','开始同一节点的新一轮',before);render()});$('accept').addEventListener('click',()=>decision('accept'));$('reject').addEventListener('click',()=>decision('reject'));$('modify').addEventListener('click',openEditor);$('applyEdit').addEventListener('click',applyEditor);$('cancelEdit').addEventListener('click',()=>{const before=snapshot();state.editing=false;state.proposal=C.clone(scenario.route);log('modify_cancel','放弃未应用的修改',before);render()});$('strategy').addEventListener('change',()=>{const before=snapshot();state.draft.strategy=$('strategy').value;state.proposal=C.clone($('strategy').value==='alternative'?scenario.alternative:scenario.route);log('strategy_change',$('strategy').value==='alternative'?'选择备选方案':'选择推荐方案',before);renderMap();renderSat()});['editAlt','editSpeed','rationale'].forEach(id=>$(id).addEventListener('change',()=>{const before=snapshot();state.draft.altitude=Number($('editAlt').value);state.draft.speed=Number($('editSpeed').value);state.draft.rationale=$('rationale').value;log('parameter_change',`${id}: ${$(id).value}`,before);renderSat()}));$('newSession').addEventListener('click',()=>{if(!confirm('结束本会话并创建新会话？已有记录会保留。'))return;newSession()});$('participant').addEventListener('change',()=>{session.participant=$('participant').value.trim()||'P001';$('participant').value=session.participant;log('participant_change','参与者编号设为 '+session.participant)});$('satMode').addEventListener('change',()=>{const previous=session.condition;session.condition=$('satMode').value;log('sat_change',`${previous} → ${session.condition}`);renderSat()});$('exportCsv').onclick=()=>exportRecords('csv');$('exportJson').onclick=()=>exportRecords('json');$('exportTop').onclick=()=>exportRecords('json');$('toggleLogs').onclick=()=>{expanded=!expanded;$('toggleLogs').textContent=expanded?'仅显示最近':'展开全部';renderLogs()};
function pointFromEvent(e){const pt=$('map').createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;return pt.matrixTransform($('map').getScreenCTM().inverse())}
$('map').addEventListener('pointerdown',e=>{const target=e.target.closest('.waypoint');if(!target)return;e.stopPropagation();if(state.editing&&window.missionMap)window.missionMap.dragging.disable();const index=Number(target.dataset.index);const route=state.editing?state.proposal:state.route;log('waypoint_select',`WP ${index}，坐标 (${route[index].join(', ')})`);$('mapHint').textContent=`WP ${index} · (${route[index].join(', ')}) 模拟米`;if(state.editing&&index>0){drag={index,before:snapshot(),start:C.clone(state.proposal[index])};$('map').setPointerCapture(e.pointerId)}});$('map').addEventListener('pointermove',e=>{if(!drag)return;const p=pointFromEvent(e);state.proposal[drag.index]=[Math.round(Math.max(35,Math.min(865,p.x))),Math.round(Math.max(35,Math.min(625,p.y)))];renderMap()});function endDrag(){if(window.missionMap)window.missionMap.dragging.enable();if(!drag)return;log('waypoint_move',`WP ${drag.index}: (${drag.start}) → (${state.proposal[drag.index]})`,drag.before);drag=null;renderSat()}$('map').addEventListener('pointerup',endDrag);$('map').addEventListener('pointercancel',endDrag);$('map').addEventListener('keydown',e=>{const target=e.target.closest('.waypoint');if(target&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const i=Number(target.dataset.index),p=(state.editing?state.proposal:state.route)[i];$('mapHint').textContent=`WP ${i} · (${p.join(', ')}) 模拟米`;log('waypoint_select',`WP ${i}，坐标 (${p})`)}if(target&&state.editing&&Number(target.dataset.index)>0&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const i=Number(target.dataset.index),before=snapshot(),p=state.proposal[i];p[0]=Math.max(35,Math.min(865,p[0]+(e.key==='ArrowRight'?5:e.key==='ArrowLeft'?-5:0)));p[1]=Math.max(35,Math.min(625,p[1]+(e.key==='ArrowDown'?5:e.key==='ArrowUp'?-5:0)));log('waypoint_move',`键盘移动 WP ${i} 至 (${p})`,before);renderMap();$('waypoints').children[i].focus();renderSat()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.status==='running'){const before=snapshot();state.status='paused';state.pausedForVisibility=true;log('visibility_pause','页面不可见，自动暂停模拟',before);render()}else if(!document.hidden&&state.triggered){log('visibility_resume','页面重新可见；决策计时包含离开时间');updateTelemetry()}});window.addEventListener('pagehide',persist);
load();applyResearchConfig();setInterval(()=>{const now=performance.now(),dt=Math.min((now-lastTick)/1000,.5);lastTick=now;if(state.status==='running'){const total=C.length(state.route),moved=state.speed*dt*4;state.simTime+=dt*4;state.progress=total?Math.min(1,state.progress+moved/total):1;state.battery=Math.max(0,scenario.battery-total*state.progress*.016);dirty=true;if(state.progress>=1){const before=snapshot();state.status='complete';log('simulation_complete','已沿确认路线返回起降区',before);render();toast('本轮任务完成，已返回起降区')}}updateTelemetry()},100);setInterval(()=>{if(dirty)persist()},1000);

function applyResearchConfig(){
  try { const config=JSON.parse(localStorage.getItem('uav-research-config-v1')||'null');
    if(!config||config.nonce===session.configNonce||state.triggered)return;
    log('session_end','研究后台启动新会话');
    $('participant').value=String(config.participant||'P001').slice(0,32);
    $('satMode').value=['action','reason','projection'].includes(config.condition)?config.condition:'action';
    newSession(true);session.configNonce=config.nonce;persist();
  } catch(e) { /* 保留现有配置 */ }
}
window.addEventListener('storage',e=>{if(e.key==='uav-research-config-v1'&&!state.triggered)applyResearchConfig()});
window.addEventListener('uav-map-action',e=>{if(session&&state)log(e.detail.type,e.detail.text)});
